+        stock_to_leave: 0.0,
+        stepover: 2.0,
+        stepdown: 50.0,
+        clearance_z: 20.0,
+        retract_z: None,
+        feed: 500.0,
+        plunge_feed: 250.0,
+        climb: true,
+        entry: Entry3D::Plunge,
+        helix_radius: 1.0,
+    }
+}
